# engine: the dbspec document set failed validation at load
SCHEMA_INVALID = "SCHEMA_INVALID"
# engine
DIALECT_UNKNOWN = "DIALECT_UNKNOWN"
# engine: structural: missing fields, wrong combination, param index out of range
